// Category C — but **deliberately not borrowed**, not “because no headless component exists.” Do not blur this distinction:
// the installed react-aria-components (1.19.0) does in fact export Toast headless components —
// `UNSTABLE_ToastRegion` · `UNSTABLE_ToastList` · `UNSTABLE_Toast` · `UNSTABLE_ToastContent` ·
// `UNSTABLE_ToastQueue`. Therefore the basis for the contract §3 A/C classification is the
// judgment below, not “availability.”
//
// Why it is not adopted (the installed version still carries the UNSTABLE_ prefix):
// we **distribute by copy-paste**. Consumers own the file, so pinning our version cannot shield
// them, and if Adobe changes the API in a minor release, the breakage lands directly in consumer
// repos. The UNSTABLE_ prefix is Adobe's own signal that “this may change,” so this distribution
// model takes that signal at face value. **Reevaluate this decision when the prefix is removed** —
// then moving to Category A and borrowing the queue/region is correct.
//
// What this gives up in return (confirmed from RAC source, not measurement — `react-aria/…/toast/useToastRegion.mjs`):
//   · `useLandmark`-based region → no F6 landmark navigation.
//   · No focus movement when the focused toast disappears (next/previous toast, or restoring the
//     previous element for pointer modality) — here focus falls to <body>. This is a real defect,
//     and the place to fix it is not this file but by reversing the decision above (hand-writing
//     the same behavior twice deepens the violation).
//   · Per-locale “Notifications” label → fixed to English here.
//
// Therefore behavior is owned directly (module store + aria-live region + auto-dismiss + accessible close).
// The queue lives in module state outside the component so toast() can be called from anywhere.
/* eslint-disable react-refresh/only-export-components --
   toast()/dismissToast() deliberately coexist in the same file as <Toaster>:
   the entire toast system must be copied as one file in copy-paste distribution (the same as sonner, etc.). */
import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import { X } from "./icons";
import { Button } from "./Button";
import { FeaturedIcon } from "./FeaturedIcon";
import type { CSSProperties, ReactNode, Ref } from "react";
import "./Toast.css";

export type ToastVariant = "info" | "success" | "warning" | "error";
export type ToastLive = "off" | "polite" | "assertive";

/** Announcement urgency → ARIA live-region role. The same axis and mapping as Alert. */
const ROLE_FOR_LIVE = { assertive: "alert", polite: "status", off: undefined } as const;

/** Whether a ReactNode slot has content to render.
 *
 *  `{node && …}` renders `0` itself when node is `0` — in `icon={count && <Bell/>}`, a count of 0
 *  exposes a stray `0` as the toast's first child, outside aria-hidden. Conversely, checking only
 *  `node != null` lets `""` or `[]` through and leaves a contentless 40px plate.
 *
 *  **The same function is duplicated in `Alert.tsx`** — because Toast must not import Alert in
 *  copy-paste distribution (the reason is in its comment). **If you fix one, fix the other too.** */
const isPresent = (node: ReactNode): boolean => {
  if (node == null || node === false || node === "") return false;
  if (Array.isArray(node)) return node.some(isPresent);
  return true;
};

export interface ToastProps {
  /**
   * Color axis.
   *
   * @default "info"
   */
  variant?: ToastVariant;
  /** Optional leading icon. It is contained in the same `FeaturedIcon` plate as Alert and receives
   *  `aria-hidden`, so the title/description text must carry the meaning. The plate sizes it from
   *  the text size, so pass `size="1em"`. When omitted, the entire plate is not rendered — it does
   *  not leave an empty space. */
  icon?: ReactNode;
  /**
   * Announcement urgency. **Decoupled from the visual variant** — a red error does not necessarily
   * mean “interrupt what is being read,” and conversely info may need immediate announcement.
   * Because `assertive` (role=alert) interrupts the current reading flow, use it only when truly
   * urgent; the default is `polite` (role=status). The same value set as Alert.
   *
   * @default "polite"
   */
  live?: ToastLive;
  /** Bold first line. */
  title: ReactNode;
  /** Optional supporting description. */
  description?: ReactNode;
  /** Milliseconds until auto-dismiss. 0 disables auto-dismiss. Defaults to 5000. */
  duration?: number;
}

interface ToastRecord extends ToastProps {
  id: string;
}

let records: ToastRecord[] = [];
const listeners = new Set<() => void>();
let counter = 0;

function emit() {
  for (const l of listeners) l();
}
function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}
function getSnapshot() {
  return records;
}

/** Adds a toast to the queue and returns its id. Callable from anywhere (including outside React). */
export function toast(options: ToastProps): string {
  const id = `sd-toast-${++counter}`;
  records = [...records, { id, ...options }];
  emit();
  return id;
}

/** Immediately removes a toast by id. */
export function dismissToast(id: string): void {
  records = records.filter((t) => t.id !== id);
  emit();
}

type ToasterPosition =
  | "top"
  | "bottom"
  | "top-start"
  | "top-end"
  | "bottom-start"
  | "bottom-end";

export interface ToasterProps {
  /**
   * Placement at a viewport corner. Defaults to bottom-end.
   *
   * @default "bottom-end"
   */
  position?: ToasterPosition;
  /** Additional class (optional). sd-toaster is always preserved. */
  className?: string;
  /** Optional inline style. */
  style?: CSSProperties;
  /** Forwarded to the underlying <div> DOM node. */
  ref?: Ref<HTMLDivElement>;
}

/** Mount once at the app root. Subscribes to the queue and renders toasts. */
export function Toaster({ position = "bottom-end", className, style, ref }: ToasterProps) {
  const items = useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
  return (
    <div
      ref={ref}
      role="region"
      aria-label="Notifications"
      data-position={position}
      className={className ? `sd-toaster ${className}` : "sd-toaster"}
      style={style}
    >
      {items.map((item) => (
        <ToastItem key={item.id} {...item} />
      ))}
    </div>
  );
}

function ToastItem({
  id,
  title,
  description,
  icon,
  variant = "info",
  live = "polite",
  duration = 5000,
}: ToastRecord) {
  // Pause auto-dismiss while the toast is hovered or holds focus — a toast must not vanish
  // mid-read. Remaining time is preserved across pauses so a brief hover doesn't reset the
  // full duration.
  //
  // This is a mitigation, NOT conformance with WCAG 2.2.1 Timing Adjustable: that criterion
  // wants the limit turned off, adjusted, or extended before it starts, and hover/focus is
  // none of the three — a keyboard user whose focus is elsewhere cannot reach the Dismiss
  // button inside the default 5000ms to trigger the pause at all. `duration: 0` is the real
  // escape, so a toast carrying an action the user must be able to reach should pass it.
  const [paused, setPaused] = useState(false);
  const remainingRef = useRef(duration);
  const startRef = useRef(0);

  useEffect(() => {
    if (!duration || paused) return;
    startRef.current = Date.now();
    const timer = setTimeout(() => dismissToast(id), remainingRef.current);
    return () => {
      clearTimeout(timer);
      remainingRef.current -= Date.now() - startRef.current;
    };
  }, [id, duration, paused]);

  return (
    <div
      role={ROLE_FOR_LIVE[live]}
      data-variant={variant}
      className="sd-toast"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocus={() => setPaused(true)}
      onBlur={() => setPaused(false)}
    >
      {/* The same leading plate Alert uses, so the two siblings share a part instead of each
          inventing its own status treatment. `sunken` because a toast is a plain white panel,
          not a tinted one — the plate has to recess into it to read at all. The glyph takes the
          variant colour from the root, which is why the plate itself sets no colour. */}
      {isPresent(icon) && (
        <FeaturedIcon aria-hidden="true" size="large" tone="sunken" className="sd-toast__icon">
          {icon}
        </FeaturedIcon>
      )}
      <div className="sd-toast__content">
        <span className="sd-toast__title sd-type-subtitle-medium">{title}</span>
        {/* `body`, not `caption` — the decision table routes by function, and this is the
            message you read, the same slot Alert/Dialog/Drawer call a body. `caption` is for
            field-adjacent helper text. The size matches Alert's because the two carry the same
            title role: a sibling pair must not split on the description alone. */}
        {isPresent(description) && (
          <span className="sd-toast__description sd-type-body-medium">{description}</span>
        )}
      </div>
      <Button
        variant="ghost"
        isIconOnly
        size="medium"
        aria-label="Dismiss"
        className="sd-toast__close"
        onPress={() => dismissToast(id)}
      >
        <X aria-hidden size="1em" />
      </Button>
    </div>
  );
}

/* Toast.css — .sd-toaster (fixed region) + .sd-toast (one notification)
   규칙: sd- 프리픽스 / 평평한 단일 클래스 / 상태·variant 는 같은 요소 data-* / Cmp 토큰만. */
.sd-toaster {
  position: fixed;
  z-index: var(--sd-toaster-z-index);
  display: flex;
  flex-direction: column;
  gap: var(--sd-toaster-gap);
  width: var(--sd-toaster-width);
  max-width: calc(100vw - var(--sd-toaster-inset) * 2);
  padding: var(--sd-toaster-inset);
  /* region 자체는 클릭 통과, 개별 토스트만 상호작용 */
  pointer-events: none;
}
.sd-toaster[data-position="bottom-end"] {
  inset-block-end: 0;
  inset-inline-end: 0;
  align-items: flex-end;
}
.sd-toaster[data-position="bottom-start"] {
  inset-block-end: 0;
  inset-inline-start: 0;
  align-items: flex-start;
}
.sd-toaster[data-position="bottom"] {
  inset-block-end: 0;
  inset-inline: 0;
  margin-inline: auto;
  align-items: center;
}
.sd-toaster[data-position="top-end"] {
  inset-block-start: 0;
  inset-inline-end: 0;
  align-items: flex-end;
}
.sd-toaster[data-position="top-start"] {
  inset-block-start: 0;
  inset-inline-start: 0;
  align-items: flex-start;
}
.sd-toaster[data-position="top"] {
  inset-block-start: 0;
  inset-inline: 0;
  margin-inline: auto;
  align-items: center;
}

/* One surface step on every side, paired with the radius that step carries — the same tier
   Alert/Dialog/Drawer sit on, preserving the brand's intended concentric surface relationship.
   `center` so the [plate · text · close] row reads as one band: a toast is usually one
   or two lines, and that is the case worth optimising. The trade is the long-body case, where
   the plate and close drift toward the middle of a tall card rather than sitting with the
   title — accepted deliberately, because a toast that long is the exception. */
.sd-toast {
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: var(--sd-toast-gap);
  width: 100%;
  padding: var(--sd-toast-padding);
  background: var(--sd-toast-background);
  color: var(--sd-toast-foreground);
  border: var(--sd-toast-border-width) solid var(--sd-toast-border);
  border-radius: var(--sd-toast-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  box-shadow: var(--sd-toast-shadow);
  animation: sd-toast-enter var(--sd-toast-animation-duration) var(--sd-easing-decelerate);
  /* Base default, so the plate is coloured even if `data-variant` is ever absent — the same
     shape Checkbox/Switch give their `-current` intermediates. The `-color-` segment is load
     bearing: `toast/icon/{info,success,…}` ARE real Cmp tokens, so a bare
     `--sd-toast-icon-current` would read as one more of them, which is exactly what contract
     §6 rule 5 forbids a local intermediate from doing. */
  --sd-toast-icon-color-current: var(--sd-toast-icon-info);
}

/* Status lives in the plate's glyph, not in a stripe. The old left accent border was drawn on a
   rounded box, so the corner curve ate both its ends and it read as a detached sliver — and it
   left Toast the one status component with no icon. The variant sets a `-current` intermediate
   rather than `color`, so it reaches the plate (which sets no colour of its own) without
   tinting the title and description, which keep inheriting the root's neutral foreground. */
.sd-toast[data-variant="info"] {
  --sd-toast-icon-color-current: var(--sd-toast-icon-info);
}
.sd-toast[data-variant="success"] {
  --sd-toast-icon-color-current: var(--sd-toast-icon-success);
}
.sd-toast[data-variant="warning"] {
  --sd-toast-icon-color-current: var(--sd-toast-icon-warning);
}
.sd-toast[data-variant="error"] {
  --sd-toast-icon-color-current: var(--sd-toast-icon-error);
}

.sd-toast__icon {
  color: var(--sd-toast-icon-color-current);
}

/* The same component-owned text inset Alert's column takes; see `Alert.css`. */
.sd-toast__content {
  display: flex;
  flex-direction: column;
  gap: var(--sd-toast-content-gap);
  flex: 1;
  min-width: 0;
}
.sd-toast__description {
  color: var(--sd-toast-description-foreground);
}

/* Close = the shared Button (variant="ghost", isIconOnly) — all look/state comes from
   Button; only the no-shrink stays here so the close keeps its width beside the content. */
.sd-toast__close {
  flex-shrink: 0;
}

@keyframes sd-toast-enter {
  from {
    opacity: 0;
    transform: translateY(var(--sd-toast-translate-enter));
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@media (prefers-reduced-motion: reduce) {
  .sd-toast {
    animation: none;
  }
}
